from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
from concurrent.futures import ThreadPoolExecutor,as_completed
from urllib.parse import urlparse,urljoin,urlunparse
from bs4 import BeautifulSoup
import hashlib,json,re,requests
P=Path.cwd();R=P/'reports/research/510300_electricity_original_publication_state_v1'
pr=json.loads((R/'protocol.json').read_text(encoding='utf-8'))
for x in pr['parents']:
 b=(P/x['path']).read_bytes()
 if hashlib.sha256(b).hexdigest()!=x['sha256']: raise RuntimeError('父原件改变，停止请求:'+x['path'])
if (R/'目录请求账本.json').exists(): raise RuntimeError('请求账本已存在，禁止重发')
(R/'raw').mkdir(exist_ok=True)
ledger=[];catalogues=[];seen={'https://www.nea.gov.cn/xwfb/index_2.htm'}
cached=P/'reports/research/510300_electricity_physical_quantity_source_qualification_v1/raw/official_news_catalogue.html'
catalogues.append({'url':'https://www.nea.gov.cn/xwfb/index_2.htm','path':str(cached.relative_to(P)).replace('\\','/'),'reused':True,'sha256':hashlib.sha256(cached.read_bytes()).hexdigest()})
def clock(): return datetime.now(ZoneInfo('Asia/Shanghai')).isoformat()
def save(n,v): (R/n).write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding='utf-8')
def fetch(url):
 parsed=urlparse(url);tag=parsed.path.rsplit('/',1)[-1];q=R/'raw'/('catalogue_'+tag)
 started=clock();z={'requested_url':url,'method':'GET','started_at':started,'automatic_redirects':False,'retries':0,'credentials_used':False}
 try:
  with requests.Session() as sess:
   sess.trust_env=False
   a=sess.get(url,timeout=(10,25),allow_redirects=False,headers={'User-Agent':'Mozilla/5.0 (compatible; public historical research)','Accept':'text/html'})
   q.write_bytes(a.content)
   z.update({'status_code':a.status_code,'received_at':clock(),'response_url':a.url,'redirect_location':a.headers.get('Location'),'bytes':len(a.content),'sha256':hashlib.sha256(a.content).hexdigest(),'raw_path':str(q.relative_to(P)).replace('\\','/'),'content_type':a.headers.get('Content-Type'),'response_encoding':a.encoding,'http_date':a.headers.get('Date')})
 except Exception as e:
  z.update({'received_at':clock(),'status_code':None,'bytes':0,'error_type':type(e).__name__,'error':str(e)})
 return z
pending=list(pr['initial_known_directory_urls'])
while pending and len(ledger)<15:
 wave=[]
 for u in pending:
  if u not in seen and len(wave)+len(ledger)<15:
   seen.add(u);wave.append(u)
 if not wave: break
 with ThreadPoolExecutor(max_workers=4) as ex:
  for fut in as_completed([ex.submit(fetch,u) for u in wave]):
   rec=fut.result();ledger.append(rec);save('目录请求账本.json',ledger)
   print('目录收件',rec['requested_url'],rec['status_code'],rec['bytes'],flush=True)
   if rec.get('status_code')==200:
    catalogues.append({'url':rec['requested_url'],'path':rec['raw_path'],'reused':False,'sha256':rec['sha256']})
 pending=[]
 for cat in catalogues:
  s=BeautifulSoup((P/cat['path']).read_bytes(),'html.parser')
  for a in s.find_all('a',href=True):
   u=urljoin(cat['url'],a['href'])
   z=urlparse(u)
   if z.netloc=='www.nea.gov.cn' and re.fullmatch(r'/xwfb/index(?:_\d+)?\.htm',z.path):
    u=urlunparse(z._replace(scheme='https',fragment=''))
    if u not in seen and u not in pending: pending.append(u)
save('实际目录与复用原件.json',catalogues)
candidates={}
for cat in catalogues:
 s=BeautifulSoup((P/cat['path']).read_bytes(),'html.parser')
 for a in s.find_all('a',href=True):
  t=a.get_text(' ',strip=True)
  if '全社会用电量' not in t: continue
  orig=urljoin(cat['url'],a['href']);z=urlparse(orig)
  if z.netloc!='www.nea.gov.cn': continue
  u=urlunparse(z._replace(scheme='https',fragment=''))
  text=a.parent.get_text(' ',strip=True)
  if len(text)>800: text=t
  candidates.setdefault(u,{'url':u,'original_anchor_url':orig,'title':t,'catalogue_url':cat['url'],'directory_context':text})
vals=sorted(candidates.values(),key=lambda x:x['url'])
save('目录实际全国用电量标题锚点.json',vals)
print(json.dumps({'实际新目录GET':len(ledger),'目录原件含复用':len(catalogues),'实际用电标题原对象':len(vals),'最早十行':vals[:10],'最新五行':vals[-5:],'未完成链接':pending},ensure_ascii=False))
